1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
22	    @Mapping(target = "displayName",
23	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "membershipPoints",
31	            expression = "java(org.springframework.samples.petclinic.mapper.OwnerMapper.membershipPoints(owner))")
32	    @Mapping(target = "membershipLevel",
33	            expression = "java(org.springframework.samples.petclinic.mapper.OwnerMapper.membershipLevel(owner))")
34	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
37	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
38	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
39	    OwnerDto toOwnerDto(Owner owner);
40	
41	    /**
42	     * The owner's canonical URL, formatted {@code '/api/owners/<id>'} where id is the owner's id.
43	     * Null when the owner has no id yet.
44	     */
45	    default String selfLink(Owner owner) {
46	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
47	    }
48	
49	    /**
50	     * The owner's stored E.164 {@code telephone} formatted for humans: the '+' country code, a space,
51	     * then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). Null when no
52	     * telephone is recorded.
53	     */
54	    default String telephoneDisplay(Owner owner) {
55	        return org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(
56	                owner.getTelephone());
57	    }
58	
59	    /**
60	     * The owner's age band, computed from {@code birthDate} against {@code registrationDate}:
61	     * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65+). Null when no
62	     * birth date is recorded.
63	     */
64	    default String ageBand(Owner owner) {
65	        if (owner.getBirthDate() == null) {
66	            return null;
67	        }
68	        java.time.LocalDate reference = owner.getRegistrationDate() != null
69	                ? owner.getRegistrationDate() : java.time.LocalDate.now();
70	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
71	        if (age < 18) {
72	            return "MINOR";
73	        }
74	        if (age < 65) {
75	            return "ADULT";
76	        }
77	        return "SENIOR";
78	    }
79	
80	    /**
81	     * The owner's derived {@code identityKey} = normalizedTelephone + '|' + (email or empty) + '|' +
82	     * householdId, the single key all duplicate detection is expressed through.
83	     */
84	    default String identityKey(Owner owner) {
85	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
86	                owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
87	    }
88	
89	    /**
90	     * The owner's preferred contact channel: {@code EMAIL} when an email is present, otherwise
91	     * {@code PHONE}.
92	     */
93	    default String contactPreference(Owner owner) {
94	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
95	    }
96	
97	    /**
98	     * The owner's salutation: the honorific {@code title}, a single space, then the {@code lastName}
99	     * when a title is present, or just the {@code lastName} when no title is given.
100	     */
101	    default String salutation(Owner owner) {
102	        String title = owner.getTitle();
103	        if (title == null || title.isBlank()) {
104	            return owner.getLastName();
105	        }
106	        return title + " " + owner.getLastName();
107	    }
108	
109	    default String initials(Owner owner) {
110	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
111	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
112	    }
113	
114	    /**
115	     * The owner's locality (region), read from the REGION component of the customerCode
116	     * ({@code <REGION>-<HASH8>}); see
117	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#regionOf}.
118	     */
119	    default String locality(Owner owner) {
120	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(
121	                owner.getCustomerCode());
122	    }
123	
124	    /**
125	     * The IANA timezone name for the owner's locality (region), from the fixed region-to-timezone
126	     * table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane); see
127	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#timezoneOf}.
128	     * Null when the region is absent or unknown.
129	     */
130	    default String timezone(Owner owner) {
131	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.timezoneOf(
132	                owner.getCustomerCode());
133	    }
134	
135	    /**
136	     * A single Luhn check digit (0-9) computed over the digits of the owner's {@code customerCode}.
137	     * Null when the customer code is absent.
138	     */
139	    default Integer checkDigit(Owner owner) {
140	        if (owner.getCustomerCode() == null) {
141	            return null;
142	        }
143	        String code = owner.getCustomerCode();
144	        int sum = 0;
145	        boolean dbl = true;
146	        for (int i = code.length() - 1; i >= 0; i--) {
147	            char c = code.charAt(i);
148	            if (c < '0' || c > '9') {
149	                continue;
150	            }
151	            int d = c - '0';
152	            if (dbl) {
153	                d *= 2;
154	                if (d > 9) {
155	                    d -= 9;
156	                }
157	            }
158	            sum += d;
159	            dbl = !dbl;
160	        }
161	        return (10 - (sum % 10)) % 10;
162	    }
163	
164	    /**
165	     * The fiscal year the {@code date} falls in, as an integer. The fiscal year starts on 1 July and is
166	     * named by the calendar year in which it ends, so 1 July 2026 - 30 June 2027 is fiscal year 2027: a
167	     * date in July or later belongs to the next calendar year's fiscal year, an earlier date to the
168	     * current calendar year's.
169	     */
170	    static int fiscalYearOf(java.time.LocalDate date) {
171	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
172	    }
173	
174	    /**
175	     * The owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of the fiscal
176	     * year the business-day-adjusted registrationDate falls in (fiscal year starting 1 July), e.g.
177	     * {@code FY27}. Null when the registration date is absent.
178	     */
179	    default String fiscalYear(Owner owner) {
180	        if (owner.getRegistrationDate() == null) {
181	            return null;
182	        }
183	        return String.format("FY%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
184	    }
185	
186	    /**
187	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
188	     * digits of the fiscal year the registrationDate falls in (fiscal year starting 1 July), e.g.
189	     * {@code NSW-1A2B3C4D-M27}. Null when either the customer code or the registration date is absent.
190	     */
191	    default String membershipNumber(Owner owner) {
192	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
193	            return null;
194	        }
195	        return String.format("%s-M%02d", owner.getCustomerCode(),
196	                fiscalYearOf(owner.getRegistrationDate()) % 100);
197	    }
198	
199	    /**
200	     * The owner's membership points. Starts at 0; add 2 when an email is present; add 1 when the owner's
201	     * name was unique on creation (namesakeCount is 0); add 2 for a household of 3 or more members; add 3
202	     * for tenure of one or more elapsed fiscal years (the current fiscal year differs from the fiscal
203	     * year the registrationDate falls in; fiscal year starting 1 July).
204	     */
205	    static int membershipPoints(Owner owner) {
206	        int points = 0;
207	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
208	        if (hasEmail) {
209	            points += 2;
210	        }
211	        Integer namesakeCount = owner.getNamesakeCount();
212	        if (namesakeCount != null && namesakeCount == 0) {
213	            points += 1;
214	        }
215	        Integer householdSize = owner.getHouseholdSize();
216	        if (householdSize != null && householdSize >= 3) {
217	            points += 2;
218	        }
219	        if (owner.getRegistrationDate() != null
220	                && fiscalYearOf(java.time.LocalDate.now())
221	                        - fiscalYearOf(owner.getRegistrationDate()) >= 1) {
222	            points += 3;
223	        }
224	        return points;
225	    }
226	
227	    /**
228	     * The owner's membership level, derived by banding {@link #membershipPoints(Owner)}: level 1 for
229	     * 0-1 points, level 2 for 2-3, level 3 for 4-5, level 4 for 6 or more.
230	     */
231	    static int membershipLevel(Owner owner) {
232	        int points = membershipPoints(owner);
233	        if (points >= 6) {
234	            return 4;
235	        }
236	        if (points >= 4) {
237	            return 3;
238	        }
239	        if (points >= 2) {
240	            return 2;
241	        }
242	        return 1;
243	    }
244	
245	    Owner toOwner(OwnerDto ownerDto);
246	
247	    @Mapping(target = "id", ignore = true)
248	    @Mapping(target = "pets", ignore = true)
249	    Owner toOwner(OwnerFieldsDto ownerDto);
250	
251	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
252	
253	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
254	
255	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
256	        OwnerPageDto ownerPageDto = new OwnerPageDto();
257	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
258	        ownerPageDto.setPage(ownerPage.getNumber());
259	        ownerPageDto.setSize(ownerPage.getSize());
260	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
261	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
262	        return ownerPageDto;
263	    }
264	}
